/*
 * Estonian host output per USB HID usage, for the four levels a key can type:
 * plain, Shift, AltGr, Shift+AltGr.
 *
 * Source of truth: firmware/keyboards/splitkb/halcyon/kyria/keymaps/keypress_hlc/layout_tables.h,
 * generated by tools/generate_layouts.py from libxkbcommon (`ee`, model pc105, evdev rules).
 * That header stores letters uppercase because it draws keycaps. Here the characters are the
 * real ones the host types: plain letters lowercase (`a`), Shift letters uppercase (`A`), and
 * `null` where the header has 0 (the key types nothing displayable at that level).
 *
 * Row shape: [hid, [plain, shift, altgr, shiftAltgr], [dead×4]]
 * `dead` marks a level that starts a dead key (the character shown is the accent it adds),
 * exactly the set libxkbcommon reports as dead_* for `ee`. A dead level whose accent has no
 * display form (hook, horn) keeps a null character.
 */
(function (KS) {
  'use strict';

  var ROWS = [
    [0x04, ['a', 'A', 'æ', 'Æ'], [0, 0, 0, 0]],
    [0x05, ['b', 'B', '“', '‘'], [0, 0, 0, 0]],
    [0x06, ['c', 'C', '¢', '©'], [0, 0, 0, 0]],
    [0x07, ['d', 'D', 'ð', 'Ð'], [0, 0, 0, 0]],
    [0x08, ['e', 'E', '€', '¢'], [0, 0, 0, 0]],
    [0x09, ['f', 'F', 'đ', 'ª'], [0, 0, 0, 0]],
    [0x0a, ['g', 'G', 'ŋ', 'Ŋ'], [0, 0, 0, 0]],
    [0x0b, ['h', 'H', 'ħ', 'Ħ'], [0, 0, 0, 0]],
    [0x0c, ['i', 'I', '→', 'ı'], [0, 0, 0, 0]],
    [0x0d, ['j', 'J', null, null], [0, 0, 1, 1]],
    [0x0e, ['k', 'K', 'ĸ', '&'], [0, 0, 0, 0]],
    [0x0f, ['l', 'L', 'ł', 'Ł'], [0, 0, 0, 0]],
    [0x10, ['m', 'M', 'µ', 'º'], [0, 0, 0, 0]],
    [0x11, ['n', 'N', '”', '’'], [0, 0, 0, 0]],
    [0x12, ['o', 'O', 'ø', 'Ø'], [0, 0, 0, 0]],
    [0x13, ['p', 'P', 'þ', 'Þ'], [0, 0, 0, 0]],
    [0x14, ['q', 'Q', '@', 'Ω'], [0, 0, 0, 0]],
    [0x15, ['r', 'R', '¶', '®'], [0, 0, 0, 0]],
    [0x16, ['s', 'S', 'š', 'Š'], [0, 0, 0, 0]],
    [0x17, ['t', 'T', 'ŧ', 'Ŧ'], [0, 0, 0, 0]],
    [0x18, ['u', 'U', '↓', '↑'], [0, 0, 0, 0]],
    [0x19, ['v', 'V', '„', '‚'], [0, 0, 0, 0]],
    [0x1a, ['w', 'W', 'ß', 'Σ'], [0, 0, 0, 0]],
    [0x1b, ['x', 'X', '»', '«'], [0, 0, 0, 0]],
    [0x1c, ['y', 'Y', '←', '¥'], [0, 0, 0, 0]],
    [0x1d, ['z', 'Z', 'ž', 'Ž'], [0, 0, 0, 0]],
    [0x1e, ['1', '!', '¹', '¡'], [0, 0, 0, 0]],
    [0x1f, ['2', '"', '@', '⅛'], [0, 0, 0, 0]],
    [0x20, ['3', '#', '£', '£'], [0, 0, 0, 0]],
    [0x21, ['4', '¤', '$', '$'], [0, 0, 0, 0]],
    [0x22, ['5', '%', '€', '⅜'], [0, 0, 0, 0]],
    [0x23, ['6', '&', '¬', '⅝'], [0, 0, 0, 0]],
    [0x24, ['7', '/', '{', '⅞'], [0, 0, 0, 0]],
    [0x25, ['8', '(', '[', '™'], [0, 0, 0, 0]],
    [0x26, ['9', ')', ']', '±'], [0, 0, 0, 0]],
    [0x27, ['0', '=', '}', '°'], [0, 0, 0, 0]],
    [0x2d, ['+', '?', '\\', '¿'], [0, 0, 0, 0]],
    [0x2e, ['´', '`', '`', '¸'], [1, 1, 0, 1]],
    [0x2f, ['ü', 'Ü', '¨', '˚'], [0, 0, 1, 1]],
    [0x30, ['õ', 'Õ', '§', '¯'], [0, 0, 0, 1]],
    [0x31, ["'", '*', '½', '˘'], [0, 0, 0, 1]],
    [0x32, ["'", '*', '½', '˘'], [0, 0, 0, 1]],
    [0x33, ['ö', 'Ö', '´', '˝'], [0, 0, 1, 1]],
    [0x34, ['ä', 'Ä', '^', '^'], [0, 0, 0, 1]],
    [0x35, ['ˇ', '~', '•', '·'], [1, 1, 0, 0]],
    [0x36, [',', ';', '<', '×'], [0, 0, 0, 0]],
    [0x37, ['.', ':', '>', '÷'], [0, 0, 0, 0]],
    [0x38, ['-', '_', '|', '˙'], [0, 0, 0, 1]],
    [0x54, ['/', '/', '/', '/'], [0, 0, 0, 0]],
    [0x55, ['*', '*', '*', '*'], [0, 0, 0, 0]],
    [0x56, ['-', '-', '-', '-'], [0, 0, 0, 0]],
    [0x57, ['+', '+', '+', '+'], [0, 0, 0, 0]],
    [0x59, ['1', '1', '1', '1'], [0, 0, 0, 0]],
    [0x5a, ['2', '2', '2', '2'], [0, 0, 0, 0]],
    [0x5b, ['3', '3', '3', '3'], [0, 0, 0, 0]],
    [0x5c, ['4', '4', '4', '4'], [0, 0, 0, 0]],
    [0x5d, ['5', '5', '5', '5'], [0, 0, 0, 0]],
    [0x5e, ['6', '6', '6', '6'], [0, 0, 0, 0]],
    [0x5f, ['7', '7', '7', '7'], [0, 0, 0, 0]],
    [0x60, ['8', '8', '8', '8'], [0, 0, 0, 0]],
    [0x61, ['9', '9', '9', '9'], [0, 0, 0, 0]],
    [0x62, ['0', '0', '0', '0'], [0, 0, 0, 0]],
    [0x63, ['.', '.', '.', '.'], [0, 0, 0, 0]],
    [0x64, ['<', '>', '|', '¦'], [0, 0, 0, 0]],
    [0x67, ['=', '=', '=', '='], [0, 0, 0, 0]],
    [0x85, ['.', '.', '.', '.'], [0, 0, 0, 0]]
  ];

  var BY_HID = {};
  var i;
  for (i = 0; i < ROWS.length; i++) {
    BY_HID[ROWS[i][0]] = ROWS[i];
  }

  KS.estonian = {
    /**
     * What a HID usage types on an Estonian host.
     * @param {number} hid USB HID usage, e.g. 0x35 for the grave key
     * @returns {{levels: Array<string|null>, dead: Array<boolean>}|null}
     */
    output: function (hid) {
      var row = typeof hid === 'number' ? BY_HID[hid] : null;
      if (!row) return null;
      return {levels: row[1].slice(), dead: row[2].map(function (d) { return d === 1; })};
    }
  };
})(globalThis.KyriaStudio = globalThis.KyriaStudio || {});
